import json,re
from collections import Counter
from html import unescape
from html.parser import HTMLParser
from pathlib import Path
s=json.loads(Path('source.json').read_text()); a=json.loads(Path('answer.json').read_text())
def txt(x):
 x=re.sub(r'<br\\s*/?>',' ',x or '',flags=re.I)
 x=re.sub(r'</(?:p|div|li|tr)>',' ',x,flags=re.I)
 return ' '.join(unescape(re.sub('<["'^>]+>'"','',x)).split())
errors=[]
allowed={'p','br','table','thead','tbody','tfoot','tr','th','td','b','strong','i','em','u','sup','sub','ul','ol','li','div','span','blockquote'}
class Check(HTMLParser):
 def handle_starttag(self,t,attrs):
  if t not in allowed: errors.append(('tag',t))
  for k,v in attrs:
   if k not in {'rowspan','colspan'} or not (v or '').isdigit(): errors.append(('attribute',k,v))
for src,obj in zip(s,a):
 n=src['number']
 for k in ['code_id','source_id','source_sha256','number']:
  if src[k]"'!=obj[k]: errors.append((n,'"'identifier',k))
 p=obj['proposed_xml']; i=obj['substantive_impact']
 for k in ['assessment','scope_limitations','new_burdens_review']:
  if len(i[k])<40: errors.append((n,'impact length',k))
 if i['version']"'!=1: errors.append((n,'"'version'))
 if p is None:
  if obj['status']"'!='"'retained_unchanged' or i['effects'] or i['classification']"'!='"'retained_necessary' or obj['classification']"'!='"'retained_necessary': errors.append((n,'retained'))
 else:
  Check().feed(p)
  for e in i['effects']:
   if len(e['source_quote'])<12 or e['source_quote'] not in txt(src['source_xml']): errors.append((n,'source_quote',e['source_quote']))
   if len(e['proposed_quote'])<12 or e['proposed_quote'] not in txt(p): errors.append((n,'proposed_quote',e['proposed_quote']))
   if not re.fullmatch('[a-z0-9]+(?:-[a-z0-9]+)*', e['measure_id']) or not 6<=len(e['measure_id'])<=96:errors.append((n,'measure_id',e['measure_id']))
 if obj.get('change_type')=='full_repeal':
  if not txt(p).startswith(('Le présent article est abrogé','Abrogé')) or len(obj['repeal_scope'])<30:errors.append((n,'repeal'))
 if obj.get('change_type')=='normative_reduction':
  if not obj.get('removed_provisions') or any(len(x)<30 for x in obj['removed_provisions']): errors.append((n,'removed_provisions'))
 if src.get('benefit_check_required') and len(obj.get('benefit_review',''))<100: errors.append((n,'benefit_review'))
print('ERRORS',len(errors))
for x in errors: print(x)
print('STATUTS',dict(Counter(x['status'] for x in a)))
print('IMPACTS',dict(Counter(x['substantive_impact']['classification'] for x in a)))
print('CHANGEMENTS',dict(Counter(x.get('change_type','sans-type') for x in a)))
print('MESURES',sorted({e['measure_id'] for x in a for e in x['substantive_impact']['effects']}))
